// A workshop's reply to the autogenerated email (ADR-033). Workshops never sign up, so a reply with its estimate or invoice attached is one of
// the two ways it sends anything (the other is the one-time link). Nobody is signed in when a reply arrives, so this stays small and every step is
// checked: the address must carry a code we made, the code must belong to a request that is still open, and a few replies at most are taken.
//
// What it does with a reply: save the message and its photos and PDFs on the job card, flagged "received by email, needs entering", and tell the
// people who handle it. It does NOT read figures out of the message: staff enter them (the owner's decision, ADR-033).
import { randomBytes } from "node:crypto";
import type { Driver } from "@/lib/db/types";
import { withLinkContext, withOrgPlatform } from "@/lib/db/tenant";
import { findTenantByToken } from "@/lib/orgs";
import { hashToken } from "@/lib/odometer/link";
import { MAX_FILE_BYTES, safeName, sniff } from "@/lib/jobcards/attachments";

export const MAX_REPLIES_PER_REQUEST = 5;
export const MAX_FILES_PER_REPLY = 6;
const CODE_RE = /^[0-9a-f]{24}$/;

export const replyDomain = () => process.env.INBOUND_REPLY_DOMAIN?.trim().toLowerCase() || null;
/** Everything needed to receive a reply. Without it the emails we send carry no reply address, only the link. */
export const inboundConfigured = () => !!replyDomain() && !!process.env.RESEND_API_KEY && !!process.env.RESEND_WEBHOOK_SECRET;

export const newReplyCode = () => randomBytes(12).toString("hex");
export const replyCodeHash = (code: string) => hashToken(code);
export const replyAddress = (code: string, domain = replyDomain()) => `w-${code}@${domain}`;

/** The code inside any of these addresses ("Name <w-code@domain>" too), or null. */
export function codeFromAddresses(addrs: string[], domain = replyDomain()): string | null {
  if (!domain) return null;
  for (const a of addrs) {
    const m = /(?:^|<)\s*w-([0-9a-f]{24})@([a-z0-9.-]+)\s*>?\s*$/i.exec(a.trim());
    if (m && m[2].toLowerCase() === domain && CODE_RE.test(m[1].toLowerCase())) return m[1].toLowerCase();
  }
  return null;
}

/** The bare address in "Name <a@b.c>" or "a@b.c", lower-cased. */
export const bareAddress = (from: string): string => (/<([^>]+)>/.exec(from)?.[1] ?? from).trim().toLowerCase();

/** The reply as the sender wrote it: the text, without the long quoted history that mail programs add below it. */
export function replyText(text: string | null | undefined, html: string | null | undefined): string {
  let t = (text && text.trim()) || (html ?? "").replace(/<(style|script)[\s\S]*?<\/\1>/gi, " ").replace(/<br\s*\/?>|<\/p>|<\/div>/gi, "\n").replace(/<[^>]+>/g, " ").replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">");
  const cut = t.search(/^\s*(On .{5,200} wrote:|-{2,}\s*Original Message|From:\s.+\nSent:)/im);
  if (cut > 0) t = t.slice(0, cut);
  t = t.split("\n").filter((l) => !l.trimStart().startsWith(">")).join("\n");
  return t.replace(/[ \t]+/g, " ").replace(/\n{3,}/g, "\n\n").trim().slice(0, 4000);
}

export type ReceivedEmail = { id: string; from: string; subject: string | null; text: string | null; html: string | null; messageId: string | null };
export type ReceivedFile = { filename: string; size: number | null; downloadUrl: string };
/** The network calls, passed in so tests need no network and the route passes the real ones (src/lib/email/resend-inbound.ts). */
export type InboundDeps = {
  fetchEmail: (emailId: string) => Promise<ReceivedEmail>;
  fetchFiles: (emailId: string) => Promise<ReceivedFile[]>;
  download: (url: string, maxBytes: number) => Promise<Uint8Array>;
  store: (path: string, bytes: Uint8Array, contentType: string) => Promise<void>;
  newId: () => string;
};

export type InboundOutcome =
  | { status: "ignored" }                                   // not an address of ours, a request that is closed, or too many replies: nothing was saved
  | { status: "filed"; emailId: string; saved: number; skipped: number };

export type Resolved = { schema: string; linkId: string; jobId: string; vendorId: string; kind: "quotation" | "invoice" };

/** The open request a reply belongs to, found by the hash of its reply code (email) or of the id of the WhatsApp message it answers (ADR-042). */
export async function resolveReplyByHash(driver: Driver, hash: string): Promise<Resolved | null> {
  const t = await findTenantByToken(driver, "reply", hash);
  if (!t) return null;
  const row = (await withOrgPlatform(driver, t.schema, (q) => q.query<{ id: string; job_card_id: string; vendor_id: string; kind: "quotation" | "invoice" }>(
    `select l.id, l.job_card_id, l.vendor_id, l.kind
       from public.quotation_links l join public.tenants t on t.id = l.tenant_id
      where l.reply_code_hash = $1 and l.revoked_at is null and l.expires_at > now() and l.replies_used < $2 and t.status = 'active'`, [hash, MAX_REPLIES_PER_REQUEST]))).rows[0];
  return row ? { schema: t.schema, linkId: row.id, jobId: row.job_card_id, vendorId: row.vendor_id, kind: row.kind } : null;
}

const resolveReply = (driver: Driver, code: string) => resolveReplyByHash(driver, replyCodeHash(code));

export async function processInboundEmail(driver: Driver, deps: InboundDeps, input: { emailId: string; addresses: string[] }): Promise<InboundOutcome> {
  const code = codeFromAddresses(input.addresses);
  if (!code) return { status: "ignored" };
  const target = await resolveReply(driver, code);
  if (!target) return { status: "ignored" };
  const open = await withLinkContext(driver, target.schema, async (q) =>
    (await q.query<{ job_no: string }>("select job_no from inbound_target($1, $2, $3)", [target.jobId, target.vendorId, target.kind])).rows[0] ?? null, "inbound_mail");
  if (!open) return { status: "ignored" };                                      // the job has moved on: nothing is filed on a closed request

  const mail = await deps.fetchEmail(input.emailId);
  const messageId = mail.messageId ?? `resend:${mail.id}`;
  const seen = await withLinkContext(driver, target.schema, async (q) => (await q.query<{ s: boolean }>("select workshop_email_seen($1) as s", [messageId])).rows[0].s, "inbound_mail");
  if (seen) return { status: "ignored" };                                      // a repeated delivery of a message that is already filed
  const all = await deps.fetchFiles(input.emailId);
  const files = all.slice(0, MAX_FILES_PER_REPLY);

  // Files first, so the one database step below either has everything or nothing to point at. Only photos and PDFs within the size limit are kept.
  const kept: { path: string; name: string; mime: string }[] = [];
  let skipped = all.length - files.length;
  for (const f of files) {
    try {
      if (f.size !== null && f.size > MAX_FILE_BYTES) { skipped++; continue; }
      const bytes = await deps.download(f.downloadUrl, MAX_FILE_BYTES);
      const mime = bytes.length > 0 && bytes.length <= MAX_FILE_BYTES ? sniff(f.filename, bytes) : null;
      if (!mime) { skipped++; continue; }
      const name = safeName(f.filename);
      const path = `${target.schema}/job_card/${target.jobId}/${deps.newId()}-${name}`;
      await deps.store(path, bytes, mime);
      kept.push({ path, name, mime });
    } catch { skipped++; }
  }

  const note = skipped > 0 ? `\n\n[${skipped} attachment${skipped > 1 ? "s were" : " was"} not saved: larger than 4 MB, not a photo or PDF, or too many.]` : "";
  const emailId = await withLinkContext(driver, target.schema, async (q) => {
    const id = (await q.query<{ id: string }>("select file_workshop_email($1, $2, $3, $4, $5, $6, $7) as id",
      [target.jobId, target.vendorId, target.kind, bareAddress(mail.from), mail.subject ?? "", replyText(mail.text, mail.html) + note, messageId])).rows[0].id;
    let saved = 0;
    for (const k of kept) {
      try { await q.query("savepoint f"); await q.query("select add_workshop_email_file($1, $2, $3, $4)", [id, k.path, k.name, k.mime]); await q.query("release savepoint f"); saved++; }
      catch { await q.query("rollback to savepoint f"); skipped++; }
    }
    return { id, saved };
  }, "inbound_mail");

  await withOrgPlatform(driver, target.schema, (q) => q.query("update public.quotation_links set replies_used = replies_used + 1 where id = $1", [target.linkId]));
  return { status: "filed", emailId: emailId.id, saved: emailId.saved, skipped };
}
